import sys; sys.path.insert(0,'/workspace/gen')
import numpy as np, xmwrite, subprocess, json, wave, os
SR=44100; RC=8363.0
def render(inst, note=49, rows=32, tag='cal', speed=6, bpm=125, cells=None):
    m=xmwrite.Module(tag,channels=2,speed=speed,bpm=bpm); m.instruments=[inst]
    pat=[[(0,0,0,0,0)]*2 for _ in range(rows)]
    if cells:
        for r,c,cell in cells: pat[r][c]=cell
    else:
        pat[0][0]=(note,1,0x40,0,0)
    m.add_pattern(rows,pat); m.order=[0]
    for f in ['gen/%s.xm'%tag,'gen/%s.wav'%tag]:
        if os.path.exists(f): os.remove(f)
    m.save('gen/%s.xm'%tag)
    o=json.loads(subprocess.run(['ft2','call','module_load',json.dumps({'path':'gen/%s.xm'%tag})],capture_output=True,text=True).stdout)
    assert not o['isError'], o
    json.loads(subprocess.run(['ft2','call','module_render',json.dumps({'path':'gen/%s.wav'%tag,'rate':SR,'bits':16,'loops':1})],capture_output=True,text=True).stdout)
    w=wave.open('gen/%s.wav'%tag); n=w.getnframes()
    return np.frombuffer(w.readframes(n),dtype=np.int16).reshape(-1,2).astype(float)
def pitch(x, t0=0.05, t1=0.9, ch=0):
    seg=x[int(t0*SR):int(t1*SR),ch]; seg=seg-seg.mean()
    if np.abs(seg).max()<30: return 0.0
    F=np.abs(np.fft.rfft(seg*np.hanning(len(seg)))); fr=np.fft.rfftfreq(len(seg),1/SR)
    i=int(F.argmax())
    if 0<i<len(F)-1:
        a,b,c=F[i-1],F[i],F[i+1]
        i=i+0.5*(a-c)/(a-2*b+c+1e-12)
    return float(fr[min(i,len(fr)-1)] if isinstance(i,float) else fr[i])
def table(L=1024, C=32, rel=0, ft=0, bits=16, harm=None, name='w'):
    """harmonic amplitudes dict k->amp; wave has C cycles in L samples."""
    ph=np.arange(L)*C/L
    y=np.zeros(L)
    if harm is None: harm={1:1.0,2:0.5,3:0.3,4:0.2}
    for k,a in harm.items(): y += a*np.sin(2*np.pi*k*ph + (k*0.7))
    y=y/np.abs(y).max()*26000
    i=xmwrite.Inst(name)
    s=xmwrite.Sample(y.astype(np.int16),bits=16,name=name,loop=(0,L),rel=rel,volume=64,finetune=ft)
    i.samples=[s]; i.note_table=[0]*96
    return i
print('--- finetune scale (L=1024,C=32 -> 261.34 Hz at ft=0) ---')
for ft in [0,32,64,127,-64,-128]:
    f=pitch(render(table(ft=ft)))
    print(f'  ft {ft:5d}: {f:8.3f} Hz  semitones vs ft0 {12*np.log2(f/261.344):+.4f}')
print('--- rel note ---')
for rel in [0,12,24,-12]:
    f=pitch(render(table(rel=rel)))
    print(f'  rel {rel:4d}: {f:8.3f}')
EOF
