def drums_full(p, bars=4, hats=True, extra_fill=None, kick_extra=()):
    for b in range(bars):
        base = b*16
        for r in range(16):
            g = base + r
            if r % 4 == 0:
                p.put(g, CH['KICK'], 49, I_KICK, 0x40)
            if r % 8 == 4:
                p.put(g, CH['SNARE'], 49, I_SNARE, 0x40)
            if hats:
                if r % 2 == 0:
                    p.put(g, CH['HAT'], 49, I_HAT, 0x10 + (40 if r % 4 == 2 else 30))
                if r == 14:
                    p.put(g, CH['PERC'], 49, I_OHAT, 0x10+34)
                if r % 4 == 2 and r % 8 == 2:
                    p.put(g, CH['HAT'], 49, I_HAT, 0x10+22)
        for e in kick_extra:
            if e[0] == b:
                p.put(base+e[1], CH['KICK'], 49, I_KICK, 0x40)
    if extra_fill:
        extra_fill(p, bars*16)

def snare_roll(p, start, count=8, vol0=26, step=4):
    for i in range(count):
        p.put(start+i*(64-start)//count if False else start+i*((ROWS-start)//count),
              CH['SNARE'], 49, I_SNARE, 0x10+min(63, vol0+i*step))

def bass_drive(p, prog, ins=None, vol=0x40, style='drive'):
    ins = ins or I_BASS
    for b, (chord, root, octv) in enumerate(prog):
        base = b*16
        for r in range(16):
            g = base + r
            lo = n(root+str(octv))
            if style == 'drive':
                if r % 4 == 0:
                    p.put(g, CH['BASS'], lo, ins, vol)
                elif r % 4 == 2:
                    p.put(g, CH['BASS'], lo, ins, vol-6)
                elif r % 8 == 7:
                    p.put(g, CH['BASS'], lo+12, ins, vol-12)
                elif r % 4 == 1:
                    p.put(g, CH['BASS'], lo, ins, vol-16)
            elif style == 'gallop':
                if r % 4 in (0,2,3):
                    p.put(g, CH['BASS'], lo + (12 if r%4==3 else 0), ins, vol)
            elif style == 'root':
                if r % 4 == 0:
                    p.put(g, CH['BASS'], lo, ins, vol)
                elif r == 14:
                    p.put(g, CH['BASS'], lo+12, ins, vol-14)
            elif style == 'none':
                pass
        # sub doubling on the beat
        if style != 'none':
            for r in (0, 8):
                p.put(base+r, CH['SUB'], n(root+str(octv-1)), I_SUB, 0x34)

def pad_block(p, prog, ins=None, ins2=None, vol=0x2C):
    ins = ins or I_PAD; ins2 = ins2 or I_PAD2
    for b, (chord, root, octv) in enumerate(prog):
        base = b*16
        tones = CHORDS[chord]
        notes = [n(t+str(octv+1)) for t in tones]
        p.put(base, CH['PAD'], notes[0], ins, vol)
        p.put(base, CH['PAD2'], notes[1], ins2, vol)
        p.put(base+1, CH['PAD'], notes[2], ins, vol-4)
        if len(notes) > 3:
            p.put(base+1, CH['PAD2'], notes[3], ins2, vol-4)
        p.put(base+14, CH['PAD'], 97)
        p.put(base+14, CH['PAD2'], 97)

def arps(p, prog, ins=None, ins2=None, vol=0x30, octv=5, every=2, ch=None):
    ch = ch or CH['ARP']
    ins = ins or I_ARP
    for b, (chord, root, o) in enumerate(prog):
        base = b*16
        seq = arp_notes(chord, octv, 8, 'updown')
        for r in range(0, 16, every):
            idx = (r//every) % len(seq)
            p.put(base+r, ch, seq[idx], ins, vol - (6 if (r//every) % 2 else 0))

def melody(p, ch, mel, ins, vol=0x40, gate=True):
    """mel: list of (start_row, note_name, duration_rows, vol_override)"""
    for item in mel:
        r, name, dur = item[0], item[1], item[2]
        v = item[3] if len(item) > 3 else vol
        note = n(name) if isinstance(name, str) else name
        if note:
            p.put(r, ch, note, ins, v, 4, 0x62)     # vibrato
        if gate and r+dur < ROWS and name not in ('===',):
            p.put(r+dur, ch, 97)
